{
  "apiVersion": 1,
  "type": "docs.detail.section",
  "package": "@astryxdesign/cli",
  "data": {
    "title": "Theme Adaptations",
    "content": [
      {
        "type": "prose",
        "text": "Use `adaptations` for opt-in token, theme-local token, and component changes under viewport width, primary-pointer precision, contrast preference, or motion preference. Conditions in one `when` are ANDed. Rules are ordinary ordered objects, and later matching writes win."
      },
      {
        "type": "code",
        "lang": "tsx",
        "code": "const acmeTheme = defineTheme({\n  name: 'acme',\n  adaptations: {\n    widthBreakpoints: {\n      sm: 640, md: 768, lg: 1024, xl: 1280, '2xl': 1536,\n    },\n    rules: [\n      {\n        when: {width: {below: 'md'}},\n        value: {tokens: {'--spacing-4': '12px'}},\n      },\n      {\n        when: {pointer: 'coarse'},\n        value: {tokens: {'--size-element-sm': '36px', '--size-element-md': '40px', '--size-element-lg': '44px'}},\n      },\n    ],\n  },\n});",
        "label": "Width and pointer adaptations"
      },
      {
        "type": "table",
        "headers": [
          "Condition",
          "Values"
        ],
        "rows": [
          [
            "width.from / width.below",
            "sm | md | lg | xl | 2xl"
          ],
          [
            "pointer",
            "coarse | fine"
          ],
          [
            "contrast",
            "more | less | no-preference"
          ],
          [
            "motion",
            "reduce | no-preference"
          ]
        ]
      },
      {
        "type": "prose",
        "text": "`widthBreakpoints` are fixed named start points. Defaults are 640 / 768 / 1024 / 1280 / 1536 CSS pixels. `from` includes its point; `below` excludes it. Breakpoint configuration alone emits no CSS."
      }
    ],
    "id": "theme-adaptations",
    "links": {
      "up": "astryx docs author-a-theme --index",
      "previous": "astryx docs author-a-theme custom-variants",
      "next": "astryx docs author-a-theme adaptation-rules"
    }
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
